import React from 'react';
import { Column, ColumnInstance, Row, SortingRule } from 'react-table';
import { PaginationProps } from '../pagination';

// eslint-disable-next-line no-shadow
export enum HeaderAllSelectionType {
  ALL_PAGE_ROWS,
  ALL_ROWS,
}

type BaseRowSelectEvent<T> = {
  data: T[] | T;
  checked: boolean;
};

export type RowSelectEvent<T> = BaseRowSelectEvent<T> & {
  rowId: string;
};

export type RowsSelectEvent<T> = BaseRowSelectEvent<T> & {
  rowIds: string[];
};

export type OnRowReturnType = {
  onClick?: (event: React.MouseEvent<HTMLTableRowElement>) => void;
  onDoubleClick?: (event: React.MouseEvent<HTMLTableRowElement>) => void;
  onContextMenu?: (event: React.MouseEvent<HTMLTableRowElement>) => void;
  onMouseEnter?: (event: React.MouseEvent<HTMLTableRowElement>) => void;
  onMouseLeave?: (event: React.MouseEvent<HTMLTableRowElement>) => void;
};

export interface OnDeselectAllProps extends HTMLButtonElement {
  onDeselectAll: () => void;
}

export interface TableProps<T> {
  columns: Column[];
  data: T[];
  initialSortBy?: SortingRule<string>[];
  fixedHeader?: boolean;
  tableWidth?: string;
  loading?: boolean;
  tableHeight?: string;
  emptyMessage?: React.ReactNode;
  loadingMessage?: string;
  search?: boolean;
  initialValueSearch?: string | number;
  searchPlaceholder?: string;
  onSearchChange?: (value: string) => void;
  cellHeight?: 'loose' | 'cozy' | 'tight';
  pagination?: Partial<PaginationProps> | false;
  onSort?: (prop: string | undefined, direction: 'ASC' | 'DESC' | undefined) => void;
  onRow?: (rowData: T, rowIndex: number) => OnRowReturnType;
  toolbarExtra?: (
    columnManager: {
      allColumns: ColumnInstance<Record<string, unknown>>[];
    },
    rowManager: {
      selectedRows: Row[];
    }
  ) => React.ReactNode;
  selectable?: {
    initialSelectedState?: { [key: string]: boolean };
    useCheckbox?: boolean;
    displayTextOneRowSelected?: string;
    displayTextMoreThanOneRowSelected?: string;
    displayTextDeselectAll?: string;
    counter?: number;
    headerSelectionType?: HeaderAllSelectionType;
    onRowSelect?: (rowSelectionEvent: RowSelectEvent<T>) => void;
    onAllPageRowsSelect?: (rowsSelectionEvent: RowsSelectEvent<T>) => void;
    onAllRowsSelect?: (rowsSelectionEvent: RowsSelectEvent<T>) => void;
    onDeselectAll?: () => void;
  };
  expandable?: {
    rowHasExpandFeature: (data: T) => boolean;
    render: (data: T) => React.ReactNode;
  };
}
